package com.sift.explorer.util;

import com.sift.explorer.R;

/**
 * The house palettes, in the picker's order. GENERATED by tools/palettes.py from ProjectForge
 * palettes.toml — do not edit; change the house palettes and run the script.
 */
public final class Palettes {

    private Palettes() {}

    public static final class Palette {
        /** Saved by this name, so adding palettes never shifts a saved choice. */
        public final String name;
        public final String label;
        public final int style;
        /** Material You, Ocean and Terminal follow the dark-mode switch; the rest are one look. */
        public final boolean followsMode;
        public final boolean mono;
        /** For a fixed palette: whether that one look is a light one. */
        public final boolean light;
        /** Swatch colours for the picker; 0 for Material You (the wallpaper decides). */
        public final int accent, background;

        Palette(String name, String label, int style, boolean followsMode, boolean mono,
                boolean light, int accent, int background) {
            this.name = name; this.label = label; this.style = style;
            this.followsMode = followsMode; this.mono = mono; this.light = light;
            this.accent = accent; this.background = background;
        }

        public boolean isDynamic() { return accent == 0; }
    }

    public static final String MATERIAL_YOU = "Material You";

    public static final Palette[] ALL = {
            new Palette("Material You", "Material You (wallpaper colours)", R.style.Theme_Sift_Palette_MaterialYou, true, false, false, 0, 0),
            new Palette("Ocean", "Ocean", R.style.Theme_Sift_Palette_Ocean, true, false, false, 0xFFAEC6FF, 0xFF0E1014),
            new Palette("Terminal", "Terminal", R.style.Theme_Sift_Palette_Terminal, true, true, false, 0xFF33FF77, 0xFF000300),
            new Palette("Trellis", "Trellis", R.style.Theme_Sift_Palette_Trellis, false, false, false, 0xFFA5B4FC, 0xFF0F1117),
            new Palette("Graphite", "Graphite", R.style.Theme_Sift_Palette_Graphite, false, false, false, 0xFF7AA2FF, 0xFF1B1B1F),
            new Palette("Blueprint", "Blueprint", R.style.Theme_Sift_Palette_Blueprint, false, false, false, 0xFF7DC3F0, 0xFF0B2A43),
            new Palette("Futuristic", "Futuristic", R.style.Theme_Sift_Palette_Futuristic, false, false, false, 0xFF4DE4FF, 0xFF030A12),
            new Palette("Neon", "Neon", R.style.Theme_Sift_Palette_Neon, false, false, false, 0xFF29C5F6, 0xFF000000),
            new Palette("SynthWave", "SynthWave", R.style.Theme_Sift_Palette_SynthWave, false, false, false, 0xFFFF3B6B, 0xFF08060D),
            new Palette("White Glow", "White Glow", R.style.Theme_Sift_Palette_WhiteGlow, false, false, false, 0xFFFFFFFF, 0xFF000000),
            new Palette("Silkscreen", "Silkscreen", R.style.Theme_Sift_Palette_Silkscreen, false, false, false, 0xFFD9A82B, 0xFF061F15),
            new Palette("Sticky Notes", "Sticky Notes", R.style.Theme_Sift_Palette_StickyNotes, false, false, true, 0xFF8A5300, 0xFFFFF3C2),
            new Palette("Amber Terminal", "Amber Terminal", R.style.Theme_Sift_Palette_AmberTerminal, false, true, false, 0xFFFFB000, 0xFF120A00),
            new Palette("Phosphor Green", "Phosphor Green", R.style.Theme_Sift_Palette_PhosphorGreen, false, true, false, 0xFF00FF0F, 0xFF001700),
            new Palette("Phosphor P31", "Phosphor P31", R.style.Theme_Sift_Palette_PhosphorP31, false, true, false, 0xFF7AF7D4, 0xFF020A09),
            new Palette("Zoro", "Zoro", R.style.Theme_Sift_Palette_Zoro, false, false, false, 0xFF1ED42A, 0xFF1A1A1A),
            new Palette("Nebula", "Nebula", R.style.Theme_Sift_Palette_Nebula, false, false, false, 0xFF22D3EE, 0xFF05070D)
    };

    /** Case, spaces and dashes do not matter ("white-glow"), as with `pf palette show`. */
    public static Palette byName(String name) {
        if (name == null) return null;
        String want = norm(name);
        for (Palette p : ALL) if (norm(p.name).equals(want)) return p;
        return null;
    }

    private static String norm(String s) {
        return s.toLowerCase(java.util.Locale.ROOT).replace(" ", "").replace("-", "").replace("_", "");
    }
}
